"""410 DPI prefix using the actual programmer/FatFS fixture generated by 412.

--compile-only validates DLL linkage without occupying the running Questa seat.
FPGA programming pins and base device are still models, not board hardware.
"""
import argparse
import sys
from pathlib import Path
from nes_delta231 import ROOT,sha

p=argparse.ArgumentParser()
p.add_argument('--build',required=True,type=Path)
p.add_argument('--out',required=True,type=Path)
p.add_argument('--fixture',required=True,type=Path,help='directory containing loader01-loader.c and loader01-disk.c from 412')
p.add_argument('--compile-only',action='store_true')
p.add_argument('--limit',type=int,default=256)
a=p.parse_args()
loader=(a.fixture/'loader01-loader.c').resolve();disk=(a.fixture/'loader01-disk.c').resolve()
assert loader.is_file() and disk.is_file()
runner=(ROOT/'tools/test_nes_nrom410_prefix.py').read_text()
def once(s,old,new):
 assert s.count(old)==1,(old,s.count(old));return s.replace(old,new)
runner=once(runner,"(ROOT/'tests/nes-nrom408/full_tb.c').read_text()",'Path('+repr(str(loader))+').read_text()')
runner=once(runner,"str(ROOT/'tests/nes-nrom408/fat_disk.c')",'str(Path('+repr(str(disk))+'))')
runner=once(runner,"'scope':'deliberately aborted before full load, actual 227 loader/FatFS host C to actual FPGA SPI/boot/loader and PSRAM pin model; no complete CRC/readback/START/STOP/base recovery or ARM execution'", "'scope':'actual programmer and loader/FatFS host C with actual FPGA SPI/boot/loader RTL and PSRAM pin model; deliberate prefix abort; modeled FPGA programmer pins and no complete CRC/readback/START/STOP/base or ARM execution'")
if a.compile_only:
 runner=once(runner," and os.environ.get('SALT_LICENSE_SERVER')=='18000@localhost'",'')
 runner=once(runner,'for label,cmd in steps:', 'for label,cmd in steps[:1]:')
 runner=once(runner,"log=(d/'simulation.log').read_text(errors='replace')", "print('NROM413 COMPILE ONLY');raise SystemExit(0)\nlog=(d/'simulation.log').read_text(errors='replace')")
sys.argv=['test_nes_nrom410_prefix.py','--build',str(a.build),'--out',str(a.out),'--limit',str(a.limit)]
exec(compile(runner,str(ROOT/'tools/test_nes_nrom410_prefix.py'),'exec'),{'__name__':'__main__','__file__':str(ROOT/'tools/test_nes_nrom410_prefix.py')})
